1027	// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
1028	// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
1029	// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
1030	// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
1031	// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
1032	// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
1033	// float64。查询只读，不改变采样值或写入计数。
1034	func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
1035		organized := organizeSeries(s.matchSeries(q))
1036	
1037		out := make([]QueryPointsSeries, 0, len(organized))
1038		for _, entry := range organized {
1039			points := seriesPointsInRange(entry.sr, q.start, q.end)
1040			if len(points) == 0 {
1041				continue
1042			}
1043			out = append(out, QueryPointsSeries{
1044				Name:   entry.ref.Name,
1045				Labels: entry.ref.Labels,
1046				Points: points,
1047			})
1048		}
1049		return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
1050	}
1051	
1052	// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
1053	// 内的采样点，供采样明细查询展示。选取、升序排列与点构造与写入快照共用
1054	// seriesPoints，区别只在传入的选取范围是闭区间而不是全部。
1055	func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
1056		return seriesPoints(sr, func(ts int64) bool { return ts >= start && ts <= end })
1057	}
1058	
1059	// runQueryWindows 只读统计固定时间窗口内的点数与均值：窗口把 [start,end]
1060	// 闭区间按 step 毫秒从 start 起连续划分，第 k 个窗口为
1061	// [start+k*step, start+(k+1)*step-1]（含首尾毫秒），最后一个截到 end，
1062	// 各序列共用同一组由 start 与 step 决定的边界——因此不为空窗口构造任何条目，
1063	// 即使区间横跨整个 int64 也不预先物化窗口表。
1064	//
1065	// 名称精确、标签子集的序列筛选与 organizeSeries 整理、序列排列次序和另两种
1066	// 查询完全一致。每条序列独立统计：先取区间内按时间戳升序的采样点，升序点流
1067	// 中落在同一窗口的点必然连续，据此一次遍历分窗累计 count 与精确有理数总和；
1068	// 只输出实际有点的窗口，按窗口起点升序，空窗口不补零，整个区间没有点的序列
1069	// 不列出，无任何命中时 series 为空数组。每个点只归入 floor((ts-start)/step)
1070	// 唯一窗口；start==end 时所有点归入唯一窗口。平均值沿用 query 的精确平均与
1071	// 居中取偶舍入，依据实际存储的 float64 值计算，正负大数抵消或总和超出
1072	// float64 范围时仍得有限结果。查询只读，不改变存储。
1073	func (s *MetricStore) runQueryWindows(q parsedQuery) *QueryWindowsResult {
1074		organized := organizeSeries(s.matchSeries(q))
1075	
1076		// diff = end - start，可能达到 2^64-1（start 为 MinInt64、end 为 MaxInt64），
1077		// 只能以 uint64 承载；窗口下标与窗口内偏移都在这个无符号区间内运算。
1078		diff := uint64(q.end) - uint64(q.start)
1079	
1080		out := make([]QueryWindowsSeries, 0, len(organized))
1081		for _, entry := range organized {
1082			points := seriesPointsInRange(entry.sr, q.start, q.end)
1083			if len(points) == 0 {
1084				continue
1085			}
1086			windows := make([]Window, 0)
1087			var curIdx uint64
1088			count := 0
1089			sum := new(big.Rat)
1090			rv := new(big.Rat)
1091			flush := func() {
1092				windows = append(windows, buildWindow(q.start, q.end, q.step, diff, curIdx, count, sum))
1093			}
1094			for i, p := range points {
1095				// 无符号偏移除以 step 得窗口下标；升序点流下标单调不减。
1096				idx := (uint64(p.Timestamp) - uint64(q.start)) / uint64(q.step)
1097				if i > 0 && idx != curIdx {
1098					flush()
1099					count = 0
1100					sum = new(big.Rat)
1101				}
1102				curIdx = idx
1103				count++
1104				// 写入侧已保证 value 有限，SetFloat64 对有限值是精确的。
1105				sum.Add(sum, rv.SetFloat64(p.Value))
1106			}
1107			flush()
1108			out = append(out, QueryWindowsSeries{
1109				Name:    entry.ref.Name,
1110				Labels:  entry.ref.Labels,
1111				Windows: windows,
1112			})
1113		}
1114		return &QueryWindowsResult{Status: "ok", Op: "query_windows", Series: out}
1115	}
1116	
1117	// buildWindow 构造一个非空窗口的统计：窗口起点是 start + idx*step，终点是
1118	// 起点加 step 减一；起点加 step 减一越过查询区间（含无符号加法溢出）时截到
1119	// end。sum 在此被精确除以 count，再按与 query 相同的居中取偶规则舍入为
1120	// float64（精确为零返回 +0）。调用方保证 0 <= idx*step <= diff。
1121	func buildWindow(start, end, step int64, diff, idx uint64, count int, sum *big.Rat) Window {
1122		startOff := idx * uint64(step)
1123		wStart := int64AtOffset(start, startOff)
1124		wEnd := end
1125		// tail <= diff-startOff 的比较不做 startOff+tail 加法，避免无符号溢出
1126		// （step 接近 2^63 时朴素相加可能绕过 2^64）。
1127		if tail := uint64(step) - 1; tail <= diff-startOff {
1128			wEnd = int64AtOffset(start, startOff+tail)
1129		}
1130		sum.Quo(sum, new(big.Rat).SetInt64(int64(count)))
1131		return Window{
1132			Start:   wStart,
1133			End:     wEnd,
1134			Count:   count,
1135			Average: ratToFloat64NearestEven(sum),
1136		}
1137	}
1138	
1139	// int64AtOffset 返回 start + off（0 <= off，且调用方保证结果不超过 MaxInt64）。
1140	// 直接做有符号相加在 start 接近 int64 下界、off 很大时会溢出，因此统一走
1141	// 无符号运算还原：start 非负时无符号相加必落在非负有符号范围；start 为负时
1142	// 以 -start 为界先回到非正区间、再跨入正区间，两个分支都不产生溢出。
1143	func int64AtOffset(start int64, off uint64) int64 {
1144		if start >= 0 {
1145			return int64(uint64(start) + off)
1146		}
1147		gap := uint64(-start) // 0 < gap <= 2^63（start 为 MinInt64 时恰为 2^63）
1148		if off <= gap {
1149			// gap-off 为 2^63 时 int64 表示恰为 MinInt64，取负仍是 MinInt64，语义正确。
1150			return -int64(gap - off)
1151		}
1152		return int64(off - gap)
1153	}
1154	
1155	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
1156	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
1157	func ratToFloat64NearestEven(x *big.Rat) float64 {
1158		if x.Sign() == 0 {
1159			return 0
1160		}
1161		num := new(big.Int).Set(x.Num())
1162		den := x.Denom()
1163		neg := num.Sign() < 0
1164		if neg {
1165			num.Neg(num)
1166		}
1167	
1168		// e 满足 2^e <= num/den < 2^(e+1)。
1169		e := floorLog2Rat(num, den)
1170		var m *big.Int
1171		scale := 0
1172		if e >= -1022 {
1173			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
1174			scale = e - 52
1175			m = roundScaledRatio(num, den, scale)
1176			if m.BitLen() == 54 {
1177				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
1178				m.Rsh(m, 1)
1179				scale++
1180			}
1181		} else {
1182			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
1183			scale = -1074
1184			m = roundScaledRatio(num, den, scale)
1185		}
1186		// m < 2^53，可以精确放入 int64 与 float64。
1187		f := math.Ldexp(float64(m.Int64()), scale)
1188		if neg {
1189			return -f
1190		}
1191		return f
1192	}
1193	
1194	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
1195	func floorLog2Rat(num, den *big.Int) int {
1196		k := num.BitLen() - den.BitLen()
1197		var t big.Int
1198		if k >= 0 {
1199			t.Lsh(den, uint(k))
1200			if num.Cmp(&t) >= 0 {
1201				return k
1202			}
1203			return k - 1
1204		}
1205		t.Lsh(num, uint(-k))
1206		if t.Cmp(den) >= 0 {
1207			return k
1208		}
1209		return k - 1
1210	}
1211	
1212	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
1213	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
1214		n := new(big.Int).Set(num)
1215		d := new(big.Int).Set(den)
1216		if scale >= 0 {
1217			d.Lsh(d, uint(scale))
1218		} else {
1219			n.Lsh(n, uint(-scale))
1220		}
1221		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
1222		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
1223		case 1:
1224			q.Add(q, big.NewInt(1))
1225		case 0:
1226			if q.Bit(0) == 1 {
1227				q.Add(q, big.NewInt(1))
1228			}
1229		}
1230		return q
1231	}
1232	
1233	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
1234	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
1235	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
1236	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
1237	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
1238	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
1239	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
1240	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
1241	func (r SeriesRef) String() string {
1242		var b strings.Builder
1243		b.WriteString(identityText(r.Name))
1244		b.WriteByte('{')
1245		for i, p := range sortedPairs(r.Labels) {
1246			if i > 0 {
1247				b.WriteByte(',')
1248			}
1249			b.WriteString(identityText(p.Key))
1250			b.WriteByte('=')
1251			b.WriteString(identityText(p.Value))
1252		}
1253		b.WriteByte('}')
1254		return b.String()
1255	}
1256	
1257	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
1258	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
1259	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
1260	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
1261	// 因此渲染结果不会把内容字符误读为标签边界。
1262	func identityText(s string) string {
1263		if s == "" || s != strings.TrimSpace(s) {
1264			return strconv.Quote(s)
1265		}
1266		for _, r := range s {
1267			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
1268				return strconv.Quote(s)
1269			}
1270		}
1271		return s
1272	}
1273	
1274	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
1275	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
1276	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
1277	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
1278	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
1279	type organizedSeries struct {
1280		sr    *storedSeries
1281		ref   SeriesRef
1282		pairs []labelPair
1283	}
1284	
1285	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
1286	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
1287	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
1288	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
1289	// 与冲突原因里的展示文字、标签的输入次序无关。
1290	func seriesLess(a, b organizedSeries) bool {
1291		if a.ref.Name != b.ref.Name {
1292			return a.ref.Name < b.ref.Name
1293		}
1294		return compareLabelPairs(a.pairs, b.pairs) < 0
1295	}
1296	
1297	// organizeSeries 是写入快照与三种查询成功结果共用的序列身份整理：对入选的每条已存序列
1298	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
1299	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，三种区间查询只
1300	// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
1301	// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
1302	// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
1303	// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
1304	// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
1305	// seriesPointsInRange 按区间选取并升序排列，固定窗口查询在区间升序点流上
1306	// 按窗口累计计数与精确求和。
1307	func organizeSeries(selected []*storedSeries) []organizedSeries {
1308		out := make([]organizedSeries, 0, len(selected))
1309		for _, sr := range selected {
1310			// 标签必须复制：成功结果是当次操作的独立记录，
1311			// 调用方修改结果标签不能改动已存序列的身份。
1312			labels := cloneLabels(sr.ref.Labels)
1313			out = append(out, organizedSeries{
1314				sr:    sr,
1315				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
1316				pairs: sortedPairs(labels),
1317			})
1318		}
1319		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
1320		return out
1321	}
1322	
1323	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，供写入快照
1324	// 展示。选取、升序排列与点构造与采样明细查询共用 seriesPoints，区别只在传入
1325	// 的选取范围是全部而不是闭区间。
1326	func allSeriesPoints(sr *storedSeries) []Point {
1327		return seriesPoints(sr, nil)
1328	}
1329	
1330	// seriesPoints 是写入快照与采样明细查询共用的采样点整理：从已存序列的点表中
1331	// 选出 keep 命中的时间戳（keep 为 nil 表示全部选取），按 timestamp 升序排列，
1332	// 每个时间戳配上点表中实际存储的 value（数值与时间戳一一对应，排序只动时间戳
1333	// 列表、不重配对值；int64 比较保留整数精度，float64 原样取出，负零保持负零）。
1334	// 返回的是新建切片与新建 Point，不持有点表的任何引用：调用方对结果的修改不
1335	// 影响存储，也不影响此前或此后取得的其他成功结果；取得结果后再写入新点，该份
1336	// 结果也不跟随存储变化。均值查询不构造这样的明细列表，只在点表上计数与求和。
1337	func seriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
1338		tsList := make([]int64, 0, len(sr.points))
1339		for ts := range sr.points {
1340			if keep != nil && !keep(ts) {
1341				continue
1342			}
1343			tsList = append(tsList, ts)
1344		}
1345		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
1346		points := make([]Point, len(tsList))
1347		for i, ts := range tsList {
1348			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
1349		}
1350		return points
1351	}
1352	
1353	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
1354	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
1355	// 三种区间查询共用同一套身份整理，各自只对命中序列统计均值、列出明细或
1356	// 按固定窗口统计。
1357	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
1358		all := make([]*storedSeries, 0, len(s.series))
1359		for _, sr := range s.series {
1360			all = append(all, sr)
1361		}
1362		organized := organizeSeries(all)
1363		views := make([]SeriesView, 0, len(organized))
1364		for _, os := range organized {
1365			views = append(views, SeriesView{
1366				Name:   os.ref.Name,
1367				Labels: os.ref.Labels,
1368				Points: allSeriesPoints(os.sr),
1369			})
1370		}
1371		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
1372	}
1373

